10| new_fn = r'''async function loadVerkle() {
11|   try {
12|     let L;
13|     try {
14|       L = await getJSON("/api/v1/lattice-history");
15|     } catch {
16|       let v;
17|       try {
18|         v = await getJSON("/api/v1/chain");
19|       } catch {
20|         v = await getJSON("/api/verkle");
21|       }
22|       L = {
23|         tip: v.tip || {},
24|         history: [],
25|         theme_histogram: {},
26|         plan: { working_open: [], agent_next: [], suggested_focus: null },
27|         chain_tail: (v.chain || []).slice(-12).map((r) => ({
28|           filename: r.filename || r.leaf,
29|           session_id: r.session_id,
30|         })),
31|         plain: { one_line: "lattice-history API unavailable — tip/chain only" },
32|         theme_basis: (v.evolution || {}).theme_basis || [],
33|         history_n: (v.tip || {}).n_leaves,
34|         tensions: [],
35|         chain_n: (v.chain || []).length,
36|       };
37|     }
38|     const tip = L.tip || {};
39|     const plan = L.plan || {};
40|     const hist = L.theme_histogram || {};
41|     const history = L.history || [];
42|     const basis = L.theme_basis || Object.keys(hist);
43|     const maxH = Math.max(1, ...Object.values(hist).map(Number), 1);
44| 
45|     const statsEl = $("#latticeStats");
46|     if (statsEl) {
47|       const alive = tip.alive ? "ALIVE" : "EMPTY";
48|       const tAvg = L.tension_avg != null ? Number(L.tension_avg).toFixed(2) : "—";
49|       const tLast = L.tension_latest != null ? Number(L.tension_latest).toFixed(2) : "—";
50|       statsEl.innerHTML = [
51|         ["tip", tip.root_short ? tip.root_short + "…" : "—"],
52|         ["leaves", tip.n_leaves ?? L.history_n ?? "—"],
53|         ["chain", L.chain_n ?? "—"],
54|         ["alive", alive],
55|         ["tension last", tLast],
56|         ["tension avg", tAvg],
57|       ]
58|         .map(
59|           ([k, v]) =>
60|             `<div class="stat"><span class="k">${esc(k)}</span><span class="v">${esc(String(v))}</span></div>`
61|         )
62|         .join("");
63|     }
64|     if ($("#latticeOneLine")) {
65|       $("#latticeOneLine").textContent =
66|         (L.plain && L.plain.one_line) || tip.last_filename || "—";
67|     }
68|     if ($("#latticeFocus")) {
69|       $("#latticeFocus").textContent = "Focus: " + (plan.suggested_focus || "none extracted");
70|     }
71|     if ($("#latticePlanList")) {
72|       const items = plan.working_open || [];
73|       $("#latticePlanList").innerHTML =
74|         items
75|           .map(
76|             (it) =>
77|               `<li><span class="pill">${esc(it.status || "open")}</span> ${esc(it.text || "")}</li>`
78|           )
79|           .join("") || "<li class='muted'>No ## Open items in working.md</li>";
80|     }
81|     if ($("#latticeAgentNext")) {
82|       const items = plan.agent_next || [];
83|       $("#latticeAgentNext").innerHTML =
84|         items
85|           .map(
86|             (it) =>
87|               `<li><span class="pill">${esc(it.status || "—")}</span> <span class="mono">${esc(
88|                 it.id || ""
89|               )}</span> ${esc(it.title || "")}</li>`
90|           )
91|           .join("") || "<li class='muted'>No agent_state next_moves (JSON)</li>";
92|     }
93|     if ($("#latticeThemes")) {
94|       const keys = basis.length ? basis : Object.keys(hist);
95|       $("#latticeThemes").innerHTML = keys
96|         .map((k) => {
97|           const n = Number(hist[k] || 0);
98|           const pct = Math.round((n / maxH) * 100);
99|           return `<div class="theme-row"><span class="mono">${esc(k)}</span>
100|             <div class="bar-track"><div class="bar-fill" style="width:${pct}%"></div></div>
101|             <span class="mono">${n}</span></div>`;
102|         })
103|         .join("");
104|     }
105|     if ($("#latticeHistory")) {
106|       const rows = history.slice().reverse();
107|       $("#latticeHistory").innerHTML =
108|         rows
109|           .map((h) => {
110|             const day = String(h.start_minute || "").slice(0, 10) || "—";
111|             const theme = h.dominant_theme || "—";
112|             const ten = h.tension_index != null ? Number(h.tension_index) : null;
113|             const w = ten != null ? Math.min(100, Math.round(ten * 100)) : 0;
114|             const sid = String(h.session_id || "").slice(0, 13);
115|             const dur =
116|               h.duration_minutes != null
117|                 ? Math.round(Number(h.duration_minutes)) + "m"
118|                 : "—";
119|             return `<div class="lat-row" title="${esc(h.session_id || "")}">
120|               <span class="t-date">${esc(day)}</span>
121|               <div>
122|                 <div class="t-theme">${esc(theme)}</div>
123|                 <div class="meta muted mono">${esc(sid)}… · ${esc(dur)}</div>
124|                 <div class="t-bar"><i style="width:${w}%"></i></div>
125|               </div>
126|               <span class="t-ten">${ten != null ? ten.toFixed(2) : "—"}</span>
127|             </div>`;
128|           })
129|           .join("") || "<p class='muted'>No evolution series yet — finish SessionEnd beads.</p>";
130|     }
131| 
132|     const root = String(tip.root || "");
133|     const lines = [
134|       "=== TIP ===",
135|       `root: ${root ? root.slice(0, 20) + "…" : "—"}`,
136|       `leaves: ${tip.n_leaves ?? "—"}`,
137|       `last: ${tip.last_filename || "—"}`,
138|       `session: ${tip.last_session_id || "—"}`,
139|       `updated: ${tip.updated_minute || "—"}`,
140|       "",
141|       "=== CHAIN TAIL ===",
142|       ...((L.chain_tail || []).slice(-10).map((r, i) => `${i + 1}. ${r.filename || r.session_id || "—"}`)),
143|       "",
144|       "paths: memory/biography/verkle_tip.json · topic_evolution.json · knot_timeline.jsonl",
145|     ];
146|     if ($("#verkleOut")) $("#verkleOut").textContent = lines.join("\n");
147|   } catch (e) {
148|     if ($("#verkleOut")) $("#verkleOut").textContent = String(e.message || e);
149|     if ($("#latticeOneLine")) $("#latticeOneLine").textContent = String(e.message || e);
150|   }
151| }
152| 
153| '''
154| 
155| p.write_text(text[:start] + new_fn + text[end:], encoding="utf-8")
156| print("ok", start, end)
